  function $(id){return document.getElementById(id)}
  function norm(v){return (v||"").toString().trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"")}
  function esc(s){return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}
  function slug(s){return norm(s).replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,80)}
  function parseNumber(v){const n=parseInt(String(v||"").replace(/[^\d]/g,""),10);return isNaN(n)?0:n}
  function compact(t){const f=fmtTime(t);return f?String(f).replace(":",""):String(t||"").replace(/[^0-9]/g,"").padEnd(4,"0").slice(0,4)}
  function showTime(t){return String(t||"").replace(":","h")}
  function parseCSV(text){const s=String(text||"").replace(/\r/g,"");const rows=[];let row=[],cur="",q=false;for(let i=0;i<s.length;i++){const ch=s[i],n=s[i+1];if(ch==='"'){if(q&&n==='"'){cur+='"';i++}else q=!q}else if(ch===","&&!q){row.push(cur);cur=""}else if(ch==="\n"&&!q){row.push(cur);rows.push(row);row=[];cur=""}else cur+=ch}row.push(cur);rows.push(row);return rows.filter(r=>r.some(c=>String(c||"").trim()!==""))}
  function findCol(headers,names){const hs=headers.map(norm);for(const n of names){const k=norm(n);const i=hs.findIndex(h=>h===k);if(i!==-1)return i}for(const n of names){const k=norm(n);const i=hs.findIndex(h=>h.includes(k));if(i!==-1)return i}return -1}
  function parseDateFR(v){const t=String(v||"").trim();if(/^\d{4}-\d{2}-\d{2}$/.test(t))return t;if(/^\d+(\.\d+)?$/.test(t)){const serial=parseFloat(t);const d=new Date(Math.round((serial-25569)*86400*1000));if(!isNaN(d.getTime()))return d.toISOString().slice(0,10)}const p=t.split(/[\/.-]/);if(p.length!==3)return null;let y=p[2];if(y.length===2)y="20"+y;return y+"-"+p[1].padStart(2,"0")+"-"+p[0].padStart(2,"0")}
  function fmtTime(v){const t=String(v||"").trim();if(/^\d+(\.\d+)?$/.test(t)){const n=parseFloat(t);if(n>=0&&n<1){const total=Math.round(n*24*60);return String(Math.floor(total/60)).padStart(2,"0")+":"+String(total%60).padStart(2,"0")}if(/^\d{3,4}$/.test(t)){const raw=t.padStart(4,"0");return raw.slice(0,2)+":"+raw.slice(2,4)}}if(/^\d{1,2}:\d{2}/.test(t)){const p=t.split(":");return p[0].padStart(2,"0")+":"+p[1].slice(0,2)}if(/^\d{1,2}h\d{0,2}$/i.test(t)){const p=t.toLowerCase().split("h");return p[0].padStart(2,"0")+":"+(p[1]||"00").padStart(2,"0")}return t.slice(0,5)}
  function minutes(t){const p=String(t||"").split(":");if(p.length<2)return null;const h=parseInt(p[0],10),m=parseInt(p[1],10);return isNaN(h)||isNaN(m)?null:h*60+m}
  function timeFromMin(m){return String(Math.floor(m/60)).padStart(2,"0")+":"+String(m%60).padStart(2,"0")}
  function durationToMinutes(v){const d=norm(v);let m=d.match(/(\d+)\s*min/);if(m)return parseInt(m[1],10);m=d.match(/(\d+)\s*h\s*(\d+)?/);if(m)return parseInt(m[1],10)*60+parseInt(m[2]||"0",10);if(d.includes("45"))return 45;if(d.includes("30"))return 30;if(d.includes("60"))return 60;return 60}
  function blockedDuration(format,fallback){const f=norm(format);const explicit=f.match(/bloque\s*(\d+)\s*min/);if(explicit)return parseInt(explicit[1],10);if(f.includes("bloque 30"))return 30;if(f.includes("bloque 1h")||f.includes("bloque 1 h"))return 60;return durationToMinutes(format||fallback)}
  function statusInfo(v){const s=norm(v);if(s.includes("refuse"))return"refused";if(s.includes("deplacer")||s.includes("verifier")||s.includes("attente"))return"pending";if(s.includes("accepte"))return"accepted";return"pending"}
  function statusLabel(s){return s==="accepted"?"Accepté":s==="refused"?"Refusé":"À vérifier"}
  function formatDate(iso){const d=DAYS.find(x=>x.iso===iso);return d?d.label:(iso||"Date à préciser")}
